1	import type {
2	  ArgumentMetadata,
3	  ContextType,
4	  RouteParamMetadata,
5	} from '@nestjs/common';
6	import {
7	  type CanActivate,
8	  BadRequestException,
9	  ForbiddenException,
10	  type HttpServer,
11	  type ParamData,
12	  type PipeTransform,
13	  type RequestMethod,
14	  SSE_ABORT_CONTROLLER,
15	} from '@nestjs/common';
16	import {
17	  AGGREGATE_PARAM_ERRORS_METADATA,
18	  type Controller,
19	  CUSTOM_ROUTE_ARGS_METADATA,
20	  HEADERS_METADATA,
21	  HTTP_CODE_METADATA,
22	  isEmptyArray,
23	  isString,
24	  REDIRECT_METADATA,
25	  RENDER_METADATA,
26	  ROUTE_ARGS_METADATA,
27	  RouteParamtypes,
28	  SSE_METADATA,
29	} from '@nestjs/common/internal';
30	import type { StandardSchemaV1 } from '@standard-schema/spec';
31	import { IncomingMessage } from 'http';
32	import { Observable } from 'rxjs';
33	import {
34	  FORBIDDEN_MESSAGE,
35	  GuardsConsumer,
36	  GuardsContextCreator,
37	} from '../guards/index.js';
38	import { ContextUtils } from '../helpers/context-utils.js';
39	import { ExecutionContextHost } from '../helpers/execution-context-host.js';
40	import {
41	  HandleResponseFn,
42	  HandlerMetadata,
43	  HandlerMetadataStorage,
44	  HandlerResponseBasicFn,
45	} from '../helpers/handler-metadata-storage.js';
46	import { STATIC_CONTEXT } from '../injector/constants.js';
47	import { InterceptorsConsumer } from '../interceptors/interceptors-consumer.js';
48	import { InterceptorsContextCreator } from '../interceptors/interceptors-context-creator.js';
49	import { PipesConsumer } from '../pipes/pipes-consumer.js';
50	import { PipesContextCreator } from '../pipes/pipes-context-creator.js';
51	import { IRouteParamsFactory } from './interfaces/route-params-factory.interface.js';
52	import {
53	  CustomHeader,
54	  RedirectResponse,
55	  RouterResponseController,
56	} from './router-response-controller.js';
57	import { HeaderStream } from './sse-stream.js';
58	
59	export interface ParamProperties {
60	  index: number;
61	  type: RouteParamtypes | string;
62	  data: ParamData;
63	  pipes: PipeTransform[];
64	  extractValue: <TRequest, TResponse>(
65	    req: TRequest,
66	    res: TResponse,
67	    next: Function,
68	  ) => any;
69	  schema?: StandardSchemaV1;
70	}
71	
72	export class RouterExecutionContext {
73	  private readonly handlerMetadataStorage = new HandlerMetadataStorage();
74	  private readonly contextUtils = new ContextUtils();
75	  private readonly responseController: RouterResponseController;
76	
77	  constructor(
78	    private readonly paramsFactory: IRouteParamsFactory,
79	    private readonly pipesContextCreator: PipesContextCreator,
80	    private readonly pipesConsumer: PipesConsumer,
81	    private readonly guardsContextCreator: GuardsContextCreator,
82	    private readonly guardsConsumer: GuardsConsumer,
83	    private readonly interceptorsContextCreator: InterceptorsContextCreator,
84	    private readonly interceptorsConsumer: InterceptorsConsumer,
85	    readonly applicationRef: HttpServer,
86	  ) {
87	    this.responseController = new RouterResponseController(applicationRef);
88	  }
89	
90	  public create(
91	    instance: Controller,
92	    callback: (...args: any[]) => unknown,
93	    methodName: string,
94	    moduleKey: string,
95	    requestMethod: RequestMethod,
96	    contextId = STATIC_CONTEXT,
97	    inquirerId?: string,
98	  ) {
99	    const contextType: ContextType = 'http';
100	    const {
101	      argsLength,
102	      fnHandleResponse,
103	      isSseHandler,
104	      paramtypes,
105	      getParamsMetadata,
106	      httpStatusCode,
107	      responseHeaders,
108	      hasCustomHeaders,
109	      aggregateParamErrors,
110	    } = this.getMetadata(
111	      instance,
112	      callback,
113	      methodName,
114	      moduleKey,
115	      requestMethod,
116	      contextType,
117	    );
118	
119	    const paramsOptions = this.contextUtils.mergeParamsMetatypes(
120	      getParamsMetadata(moduleKey, contextId, inquirerId),
121	      paramtypes,
122	    );
123	    const pipes = this.pipesContextCreator.create(
124	      instance,
125	      callback,
126	      moduleKey,
127	      contextId,
128	      inquirerId,
129	    );
130	    const guards = this.guardsContextCreator.create(
131	      instance,
132	      callback,
133	      moduleKey,
134	      contextId,
135	      inquirerId,
136	    );
137	    const interceptors = this.interceptorsContextCreator.create(
138	      instance,
139	      callback,
140	      moduleKey,
141	      contextId,
142	      inquirerId,
143	    );
144	
145	    const fnCanActivate = this.createGuardsFn(
146	      guards,
147	      instance,
148	      callback,
149	      contextType,
150	    );
151	    const fnApplyPipes = this.createPipesFn(
152	      pipes,
153	      paramsOptions,
154	      aggregateParamErrors,
155	    );
156	
157	    const handler =
158	      <TRequest, TResponse>(
159	        args: any[],
160	        req: TRequest,
161	        res: TResponse,
162	        next: Function,
163	      ) =>
164	      async () => {
165	        fnApplyPipes && (await fnApplyPipes(args, req, res, next));
166	        return callback.apply(instance, args);
167	      };
168	
169	    return async <TRequest, TResponse>(
170	      req: TRequest,
171	      res: TResponse,
172	      next: Function,
173	    ) => {
174	      const args = this.contextUtils.createNullArray(argsLength);
175	      fnCanActivate && (await fnCanActivate([req, res, next]));
176	
177	      this.responseController.setStatus(res, httpStatusCode);
178	      hasCustomHeaders &&
179	        this.responseController.setHeaders(res, responseHeaders);
180	
181	      if (isSseHandler) {
182	        // Attach a per-request AbortController before the handler runs so async
183	        // @Sse() handlers can observe client disconnects via @SseSignal() during
184	        // their setup. The controller is aborted in RouterResponseController.sse()
185	        // when the underlying connection closes.
186	        this.attachSseAbortSignal(req);
187	      }
188	
189	      const resultOrDeferred = this.interceptorsConsumer.intercept(
190	        interceptors,
191	        [req, res, next],
192	        instance,
193	        callback,
194	        handler(args, req, res, next),
195	        contextType,
196	      );
197	      const result = isSseHandler ? resultOrDeferred : await resultOrDeferred;
198	      await (fnHandleResponse as HandlerResponseBasicFn)(result, res, req);
199	    };
200	  }
201	
202	  public getMetadata<TContext extends ContextType = ContextType>(
203	    instance: Controller,
204	    callback: (...args: any[]) => any,
205	    methodName: string,
206	    moduleKey: string,
207	    requestMethod: RequestMethod,
208	    contextType: TContext,
209	  ): HandlerMetadata {
210	    const cacheMetadata = this.handlerMetadataStorage.get(instance, methodName);
211	    if (cacheMetadata) {
212	      return cacheMetadata;
213	    }
214	    const metadata =
215	      this.contextUtils.reflectCallbackMetadata(
216	        instance,
217	        methodName,
218	        ROUTE_ARGS_METADATA,
219	      ) || {};
220	    const keys = Object.keys(metadata);
221	    const argsLength = this.contextUtils.getArgumentsLength(keys, metadata);
222	    const paramtypes = this.contextUtils.reflectCallbackParamtypes(
223	      instance,
224	      methodName,
225	    );
226	
227	    const contextFactory = this.contextUtils.getContextFactory(
228	      contextType,
229	      instance,
230	      callback,
231	    );
232	    const getParamsMetadata = (
233	      moduleKey: string,
234	      contextId = STATIC_CONTEXT,
235	      inquirerId?: string,
236	    ) =>
237	      this.exchangeKeysForValues(
238	        keys,
239	        metadata,
240	        moduleKey,
241	        contextId,
242	        inquirerId,
243	        contextFactory,
244	      );
245	
246	    const paramsMetadata = getParamsMetadata(moduleKey);
247	    const isResponseHandled = this.isResponseHandled(
248	      instance,
249	      methodName,
250	      paramsMetadata,
251	    );
252	
253	    const httpRedirectResponse = this.reflectRedirect(callback);
254	    const fnHandleResponse = this.createHandleResponseFn(
255	      callback,
256	      isResponseHandled,
257	      httpRedirectResponse,
258	    );
259	    const isSseHandler = !!this.reflectSse(callback);
260	
261	    const httpCode = this.reflectHttpStatusCode(callback);
262	    const httpStatusCode =
263	      httpCode ?? this.responseController.getStatusByMethod(requestMethod);
264	
265	    const aggregateParamErrors = this.reflectAggregateParamErrors(callback);
266	
267	    const responseHeaders = this.reflectResponseHeaders(callback);
268	    const hasCustomHeaders = !isEmptyArray(responseHeaders);
269	    const handlerMetadata: HandlerMetadata = {
270	      argsLength,
271	      fnHandleResponse,
272	      isSseHandler,
273	      paramtypes,
274	      getParamsMetadata,
275	      httpStatusCode,
276	      hasCustomHeaders,
277	      responseHeaders,
278	      aggregateParamErrors,
279	    };
280	    this.handlerMetadataStorage.set(instance, methodName, handlerMetadata);
281	    return handlerMetadata;
282	  }
283	
284	  public reflectRedirect(
285	    callback: (...args: unknown[]) => unknown,
286	  ): RedirectResponse {
287	    return Reflect.getMetadata(REDIRECT_METADATA, callback);
288	  }
289	
290	  public reflectHttpStatusCode(
291	    callback: (...args: unknown[]) => unknown,
292	  ): number {
293	    return Reflect.getMetadata(HTTP_CODE_METADATA, callback);
294	  }
295	
296	  public reflectRenderTemplate(
297	    callback: (...args: unknown[]) => unknown,
298	  ): string {
299	    return Reflect.getMetadata(RENDER_METADATA, callback);
300	  }
301	
302	  public reflectResponseHeaders(
303	    callback: (...args: unknown[]) => unknown,
304	  ): CustomHeader[] {
305	    return Reflect.getMetadata(HEADERS_METADATA, callback) || [];
306	  }
307	
308	  public reflectSse(callback: (...args: unknown[]) => unknown): string {
309	    return Reflect.getMetadata(SSE_METADATA, callback);
310	  }
311	
312	  public reflectAggregateParamErrors(
313	    callback: (...args: unknown[]) => unknown,
314	  ): boolean {
315	    return !!Reflect.getMetadata(AGGREGATE_PARAM_ERRORS_METADATA, callback);
316	  }
317	
318	  public exchangeKeysForValues(
319	    keys: string[],
320	    metadata: Record<number, RouteParamMetadata>,
321	    moduleContext: string,
322	    contextId = STATIC_CONTEXT,
323	    inquirerId?: string,
324	    contextFactory?: (args: unknown[]) => ExecutionContextHost,
325	  ): ParamProperties[] {
326	    this.pipesContextCreator.setModuleContext(moduleContext);
327	
328	    return keys.map(key => {
329	      const { index, data, pipes: pipesCollection, schema } = metadata[key];
330	      const pipes = this.pipesContextCreator.createConcreteContext(
331	        pipesCollection,
332	        contextId,
333	        inquirerId,
334	      );
335	      const type = this.contextUtils.mapParamType(key);
336	
337	      if (key.includes(CUSTOM_ROUTE_ARGS_METADATA)) {
338	        const { factory } = metadata[key];
339	        const customExtractValue = this.contextUtils.getCustomFactory(
340	          factory,
341	          data,
342	          contextFactory!,
343	        );
344	        return {
345	          index,
346	          extractValue: customExtractValue,
347	          type,
348	          data,
349	          pipes,
350	          schema,
351	        };
352	      }
353	      const numericType = Number(type);
354	      const extractValue = <TRequest, TResponse>(
355	        req: TRequest,
356	        res: TResponse,
357	        next: Function,
358	      ) =>
359	        this.paramsFactory.exchangeKeyForValue(numericType, data, {
360	          req: req as Record<string, any>,
361	          res,
362	          next,
363	        });
364	      return { index, extractValue, type: numericType, data, pipes, schema };
365	    });
366	  }
367	
368	  public async getParamValue<T>(
369	    value: T,
370	    metadata: ArgumentMetadata,
371	    pipes: PipeTransform[],
372	  ): Promise<unknown> {
373	    if (!isEmptyArray(pipes)) {
374	      return this.pipesConsumer.apply(value, metadata, pipes);
375	    }
376	    return value;
377	  }
378	
379	  public isPipeable(type: number | string): boolean {
380	    return (
381	      type === RouteParamtypes.BODY ||
382	      type === RouteParamtypes.RAW_BODY ||
383	      type === RouteParamtypes.QUERY ||
384	      type === RouteParamtypes.PARAM ||
385	      type === RouteParamtypes.HEADERS ||
386	      type === RouteParamtypes.FILE ||
387	      type === RouteParamtypes.FILES ||
388	      isString(type)
389	    );
390	  }
391	
392	  public isParamErrorAggregated(type: number | string): boolean {
393	    return type === RouteParamtypes.PARAM || type === RouteParamtypes.QUERY;
394	  }
395	
396	  public createGuardsFn<TContext extends string = ContextType>(
397	    guards: CanActivate[],
398	    instance: Controller,
399	    callback: (...args: any[]) => any,
400	    contextType?: TContext,
401	  ): ((args: any[]) => Promise<void>) | null {
402	    const canActivateFn = async (args: any[]) => {
403	      const canActivate = await this.guardsConsumer.tryActivate<TContext>(
404	        guards,
405	        args,
406	        instance,
407	        callback,
408	        contextType,
409	      );
410	      if (!canActivate) {
411	        throw new ForbiddenException(FORBIDDEN_MESSAGE);
412	      }
413	    };
414	    return guards.length ? canActivateFn : null;
415	  }
416	
417	  public createPipesFn(
418	    pipes: PipeTransform[],
419	    paramsOptions: (ParamProperties & { metatype?: any })[],
420	    aggregateParamErrors = false,
421	  ) {
422	    const resolveParamValue = async <TRequest, TResponse>(
423	      param: ParamProperties & { metatype?: any },
424	      args: any[],
425	      req: TRequest,
426	      res: TResponse,
427	      next: Function,
428	    ) => {
429	      const {
430	        index,
431	        extractValue,
432	        type,
433	        data,
434	        metatype,
435	        pipes: paramPipes,
436	        schema,
437	      } = param;
438	      const value = extractValue(req, res, next);
439	
440	      args[index] = this.isPipeable(type)
441	        ? await this.getParamValue(
442	            value,
443	            { metatype, type, data, schema } as ArgumentMetadata,
444	            pipes.concat(paramPipes),
445	          )
446	        : value;
447	    };
448	
449	    const pipesFn = async <TRequest, TResponse>(
450	      args: any[],
451	      req: TRequest,
452	      res: TResponse,
453	      next: Function,
454	    ) => {
455	      if (!aggregateParamErrors) {
456	        await Promise.all(
457	          paramsOptions.map(param =>
458	            resolveParamValue(param, args, req, res, next),
459	          ),
460	        );
461	        return;
462	      }
463	
464	      // @Param()/@Query() pipes are executed serially, in parameter-index
465	      // order, and their rejections are collected and rethrown as a single
466	      // BadRequestException. Pipes bound to any other parameter keep the
467	      // existing fail-fast path (their errors propagate immediately).
468	      //
469	      // @Headers() parameters form an independent input domain: their pipes
470	      // always run and the transformed values are handed to the handler, but
471	      // a header pipe failure aborts the resolution immediately. The header
472	      // exception is never merged into the collected @Param()/@Query()
473	      // messages - any messages collected so far are discarded with this
474	      // request, so exception filters only observe the header exception.
475	      const orderedParams = [...paramsOptions].sort(
476	        (a, b) => a.index - b.index,
477	      );
478	      const messages: unknown[] = [];
479	      for (const param of orderedParams) {
480	        if (!this.isParamErrorAggregated(param.type)) {
481	          await resolveParamValue(param, args, req, res, next);
482	          continue;
483	        }
484	        try {
485	          await resolveParamValue(param, args, req, res, next);
486	        } catch (err) {
487	          // Only parameter validation errors are aggregated; any other
488	          // exception keeps the existing fail-fast path.
489	          if (!(err instanceof BadRequestException)) {
490	            throw err;
491	          }
492	          messages.push(...this.extractParamErrorMessages(err));
493	        }
494	      }
495	      if (messages.length > 0) {
496	        throw new BadRequestException(messages);
497	      }
498	    };
499	    return paramsOptions.length ? pipesFn : null;
500	  }
501	
502	  private extractParamErrorMessages(error: BadRequestException): unknown[] {
503	    const response = error.getResponse();
504	    if (typeof response === 'object' && response !== null) {
505	      const { message } = response as Record<string, unknown>;
506	      if (message !== undefined) {
507	        return Array.isArray(message) ? message : [message];
508	      }
509	    }
510	    return [response];
511	  }
512	
513	  public createHandleResponseFn(
514	    callback: (...args: unknown[]) => unknown,
515	    isResponseHandled: boolean,
516	    redirectResponse?: RedirectResponse,
517	    httpStatusCode?: number,
518	  ): HandleResponseFn {
519	    const renderTemplate = this.reflectRenderTemplate(callback);
520	    if (renderTemplate) {
521	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
522	        return await this.responseController.render(
523	          result,
524	          res,
525	          renderTemplate,
526	        );
527	      };
528	    }
529	    if (redirectResponse && isString(redirectResponse.url)) {
530	      return async <TResult, TResponse>(result: TResult, res: TResponse) => {
531	        await this.responseController.redirect(result, res, redirectResponse);
532	      };
533	    }
534	    const isSseHandler = !!this.reflectSse(callback);
535	    if (isSseHandler) {
536	      return async <
537	        TResult extends Observable<unknown> = any,
538	        TResponse extends HeaderStream = any,
539	        TRequest extends IncomingMessage = any,
540	      >(
541	        result: TResult,
542	        res: TResponse,
543	        req: TRequest,
544	      ) => {
545	        const rawResponse = (res as { raw?: TResponse }).raw ?? res;
546	        await this.responseController.sse(
547	          result,
548	          rawResponse,
549	          (req as any).raw || req,
550	          {
551	            additionalHeaders: res.getHeaders?.(),
552	            statusCode:
553	              (res as { statusCode?: number }).statusCode ??
554	              (rawResponse as { statusCode?: number }).statusCode,
555	          },
556	        );
557	      };
558	    }
559	    return async <TResult, TResponse>(result: TResult, res: TResponse) => {
560	      result = await this.responseController.transformToResult(result);
561	      !isResponseHandled &&
562	        (await this.responseController.apply(result, res, httpStatusCode));
563	      return res;
564	    };
565	  }
566	
567	  private isResponseHandled(
568	    instance: Controller,
569	    methodName: string,
570	    paramsMetadata: ParamProperties[],
571	  ): boolean {
572	    const hasResponseOrNextDecorator = paramsMetadata.some(
573	      ({ type }) =>
574	        type === RouteParamtypes.RESPONSE || type === RouteParamtypes.NEXT,
575	    );
576	    const isPassthroughEnabled = this.contextUtils.reflectPassthrough(
577	      instance,
578	      methodName,
579	    );
580	    return hasResponseOrNextDecorator && !isPassthroughEnabled;
581	  }
582	
583	  private attachSseAbortSignal<TRequest>(req: TRequest): void {
584	    const carrier = req as TRequest & {
585	      raw?: unknown;
586	      [SSE_ABORT_CONTROLLER]?: AbortController;
587	    };
588	    // Attach to both the framework request and its raw form (when present), since
589	    // @SseSignal() reads from the execution-context request while
590	    // RouterResponseController.sse() operates on the raw request.
591	    if (!carrier[SSE_ABORT_CONTROLLER]) {
592	      carrier[SSE_ABORT_CONTROLLER] = new AbortController();
593	    }
594	    if (carrier.raw && !(carrier.raw as object)[SSE_ABORT_CONTROLLER]) {
595	      (carrier.raw as object)[SSE_ABORT_CONTROLLER] =
596	        carrier[SSE_ABORT_CONTROLLER];
597	    }
598	  }
599	}
