23	/**
24	 * Per-process counters used by the request-isolation suites. The aggregation
25	 * state itself is per-request; these counters only let tests observe how many
26	 * pipes/handlers ran for a sequence of requests. They are reset in every test's
27	 * beforeEach via {@link resetIsolationState}.
28	 */
29	export const isolationState: {
30	  pipeCalls: string[];
31	  handlerCalls: Record<string, number>;
32	} = {
33	  pipeCalls: [],
34	  handlerCalls: {},
