49	class NumberPipe implements PipeTransform<string, number> {
50	  constructor(private readonly errorMessage: string) {}
51	
52	  transform(value: string): number {
53	    isolationState.pipeCalls.push(this.errorMessage);
54	    const parsed = Number(value);
55	    if (Number.isNaN(parsed) || value.trim() === '') {
56	      throw new BadRequestException(this.errorMessage);
57	    }
58	    return parsed;
59	  }
