67	    private readonly errorMessage: string,
68	    private readonly delayMs: number,
69	  ) {}
70	
71	  async transform(value: string): Promise<number> {
72	    isolationState.pipeCalls.push(this.errorMessage);
73	    await new Promise(resolve => setTimeout(resolve, this.delayMs));
74	    const parsed = Number(value);
75	    if (Number.isNaN(parsed) || value.trim() === '') {
76	      throw new BadRequestException(this.errorMessage);
77	    }
