124	class HeaderNumberPipe implements PipeTransform<string | undefined, number> {
125	  transform(value: string | undefined): number {
126	    isolationState.pipeCalls.push('H');
127	    const parsed = Number(value);
128	    if (
129	      value === undefined ||
