166	  catch(exception: BadRequestException, host: ArgumentsHost) {
167	    const { httpAdapter } = this.adapterHost;
168	    const response = host.switchToHttp().getResponse();
169	    const responseBody = exception.getResponse() as { message: unknown };
170	    // Record every invocation so tests can assert the filter sees the
171	    // aggregated exception exactly once (never per-parameter exceptions).
172	    MyParamFilter.received.push({
173	      status: exception.getStatus(),
174	      message: responseBody.message,
175	    });
176	    const count = Array.isArray(responseBody.message)
177	      ? responseBody.message.length
178	      : 1;
179	    httpAdapter.reply(response, { code: 'PARAMS_INVALID', count }, 422);
180	  }
