187	  constructor(private readonly adapterHost: HttpAdapterHost) {}
188	
189	  catch(exception: unknown, host: ArgumentsHost) {
190	    const { httpAdapter } = this.adapterHost;
191	    const response = host.switchToHttp().getResponse();
192	    MyWideFilter.last = {
193	      name: (exception as Error)?.name,
194	      status:
195	        typeof (exception as { getStatus?: () => number })?.getStatus ===
196	        'function'
197	          ? (exception as { getStatus: () => number }).getStatus()
198	          : undefined,
199	    };
